/**
 * The embed entry point: one function a third-party page calls to mount the
 * creator into an element it owns. No framework required on the host side.
 */

import { createRoot, type Root } from 'react-dom/client';

import { EventCreator, type EventCreatorProps } from './EventCreator';
import { ensureEventCreatorStyles } from './styles';

export interface EventCreatorEmbed {
  /** Re-render with new props (a fresh prefill, a different default format). */
  update(props: EventCreatorProps): void;
  unmount(): void;
}

/**
 * Mounts the creator into `target` (an element or a CSS selector).
 * Throws when the selector matches nothing — a silent no-op inside a host page is
 * far harder to debug than a thrown error.
 */
export function mountEventCreator(
  target: Element | string,
  props: EventCreatorProps = {},
): EventCreatorEmbed {
  const element = typeof target === 'string' ? document.querySelector(target) : target;
  if (element === null) throw new Error(`mountEventCreator: no element matches ${String(target)}`);

  ensureEventCreatorStyles();
  const root: Root = createRoot(element);
  root.render(<EventCreator {...props} />);

  return {
    update: (next) => root.render(<EventCreator {...next} />),
    unmount: () => root.unmount(),
  };
}
