/** A host's partial catalogue over the English one. Anything untranslated stays English. */
export function mergeMessages(
  overrides: Partial<EventCreatorMessages> | undefined,
): EventCreatorMessages {
  if (overrides === undefined) return EN_MESSAGES;
  return {
    ...EN_MESSAGES,
    ...overrides,
    problems: { ...EN_MESSAGES.problems, ...overrides.problems },
    problemFields: { ...EN_MESSAGES.problemFields, ...overrides.problemFields },
  };
}

/** `{name}` → value. Anything the caller doesn't supply is left as it stands. */
export function fill(template: string, values: Readonly<Record<string, string | number>>): string {
  return template.replace(/\{(\w+)\}/g, (whole, name: string) =>
    name in values ? String(values[name]) : whole,
  );
}

/**
 * The form of a count-bearing string this language uses for this number.
 *
 * `Intl.PluralRules` decides, so Polish gets its four forms and Japanese its one, and a catalogue
 * that supplies only `other` still renders — which is what makes a half-finished translation
 * degrade to slightly-wrong grammar rather than to a missing string.
 */
export function plural(
  forms: PluralForms,
  count: number,
  locale: string | undefined,
  values: Readonly<Record<string, string | number>> = {},
): string {
  let rule: Intl.LDMLPluralRule = 'other';
  try {
    rule = new Intl.PluralRules(locale).select(count);
  } catch {
    // An unparseable tag, or a runtime without PluralRules: `other` is every language's fallback.
  }
  return fill(forms[rule] ?? forms.other, { count, ...values });
}

/**
 * The ceiling a `too-long`/`too-many` message names, by the field it was raised against. Read
 * from the validator's own limits rather than written out here, so a message cannot promise a
 * number the check does not enforce.
 */
const LIMIT_FOR: Readonly<Record<string, number>> = {
  title: LIMITS.title,
  location: LIMITS.location,
  description: LIMITS.description,
  url: LIMITS.url,
  attendees: LIMITS.attendees,
  remindersMinutesBefore: LIMITS.reminders,
  'recurrence.count': LIMITS.recurrenceCount,
};

/**
 * A validation problem in the reader's language, falling back to the validator's own English.
 *
 * The fallback is the point of the design: a catalogue that has not been updated for a newly
 * added check still shows the check's own message, in English, rather than a key or a blank.
 */
export function problemMessage(problem: EventProblem, messages: EventCreatorMessages): string {
  // `attendees[0].email` and `remindersMinutesBefore[3]` are one message each, not one per row.
  const field = problem.field.replace(/\[\d+\]/g, '');
  const template = messages.problems[`${problem.code}:${field}`] ?? messages.problems[problem.code];
  if (template === undefined) return problem.message;
  return fill(template, {
    field: messages.problemFields[field] ?? field,
    limit: LIMIT_FOR[field] ?? 0,
  });
}
